// CAS-41 a CAS-60 · costos, reportes, importación y recuperación (sección 29).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import ExcelJS from 'exceljs';
import { caso, ejecutar, escenario, TINY_JPG } from './arnes.mjs';
import { startEnv } from '../tests/helpers.js';
import { Store, validateAll } from '../server/core/store.js';
import { AuthStore } from '../server/core/auth.js';
import { restoreInto, readBackup } from '../server/core/backup.js';
import { exportPackage, importPackageInto } from '../server/core/package.js';
const st = async (c, m, u, b, o) => (await c.try(m, u, b, o)).status;
const saldo = async (D, code) => (await D.get('/api/cash/accounts')).items.find((a) => a.code === code).balance;
const tmp = (p) => fs.mkdtempSync(path.join(os.tmpdir(), p));
const gasto = (S, aux, o = {}) => aux.post('/api/expenses', { supplierId: S.prov, docDate: '2026-08-25', description: 'Gasto de auditoría', categoryId: S.cat.Adhesivo, voucherTypeId: S.voucher.Factura, subtotal: '1000', tax: '0', total: '1000', ...o });

caso('CAS-41', 'Costo distribuido', ['GAS-03', 'GAS-14'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const aux = await t.env.as('aux'); const g = await gasto(S, aux, { reference: 'F-41' });
  t.ok('Distribuir $700 + $400 sobre $1,000', 422, await st(aux, 'PUT', `/api/expenses/${g.id}/allocations`, { allocations: [{ target: 'obra', workId: S.A, amount: '700' }, { target: 'obra', workId: S.B, amount: '400' }] }));
  await aux.put(`/api/expenses/${g.id}/allocations`, { allocations: [{ target: 'obra', workId: S.A, method: 'porcentaje', pct: '70' }, { target: 'obra', workId: S.B, method: 'porcentaje', pct: '30' }] });
  let e = await D.get(`/api/expenses/${g.id}`); t.ok('70 % / 30 %', ['700.00', '300.00'], e.allocations.map((a) => a.amount)); await D.post(`/api/expenses/${g.id}/status`, { status: 'autorizado' });
  const porObra = async () => { const r = await D.get('/api/reports/costos'); return [r.items.filter((x) => x.workId === S.A || /Obra A/.test(x.work)).reduce((s, x) => s + Number(x.amount), 0).toFixed(2), r.items.filter((x) => x.workId === S.B || /Obra B/.test(x.work)).reduce((s, x) => s + Number(x.amount), 0).toFixed(2), r.totals.amount.value]; };
  t.ok('Costo por obra y total', ['700.00', '300.00', '1000.00'], await porObra());
  const re = await D.try('PUT', `/api/expenses/${g.id}/allocations`, { allocations: [{ target: 'obra', workId: S.A, amount: '600' }, { target: 'obra', workId: S.B, amount: '400' }], reason: 'Reclasificación entre obras (auditoría)' }); t.nota('Reclasificar a $600/$400 con el gasto ya autorizado', `${re.status} ${re.data.message || ''} ${re.data.fix || ''}`);
  t.ok('Reclasificación entre obras admitida con historial', 200, re.status); t.ok('El total de empresa no cambia al reclasificar', re.status === 200 ? ['600.00', '400.00', '1000.00'] : ['700.00', '300.00', '1000.00'], await porObra());
  const hist = await (await t.env.as('aud')).get(`/api/audit?objectId=${g.id}`); t.nota('Eventos de auditoría del gasto', JSON.stringify(hist.items.map((x) => x.action)));
  t.ok('Reclasificar sin facultad (auxiliar) sobre gasto autorizado', true, [403, 404, 409].includes(await st(aux, 'PUT', `/api/expenses/${g.id}/allocations`, { allocations: [{ target: 'obra', workId: S.A, amount: '1000' }] })));
});

caso('CAS-42', 'Gasto y pago separados', ['GAS-02', 'GAS-05', 'PAG-15'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const aux = await t.env.as('aux'); const g = await gasto(S, aux, { reference: 'F-42', allocations: [{ target: 'obra', workId: S.A, amount: '1000' }] });
  t.ok('Un gasto sin autorizar no es costo', '0.00', (await D.get('/api/reports/costos')).totals.amount?.value ?? '0.00'); const au = await D.post(`/api/expenses/${g.id}/status`, { status: 'autorizado' });
  t.ok('Autorizado: costo $1,000 y desembolso cero', ['1000.00', '500000.00'], [(await D.get('/api/reports/costos')).totals.amount.value, await saldo(D, 'CAJA')]); let e = await D.get(`/api/expenses/${g.id}`); t.ok('Estado de pago', 'sin_pago', e.payStatus);
  await S.pagar(au.obligationId, '1000'); e = await D.get(`/api/expenses/${g.id}`); t.ok('Pagado', 'pagado', e.payStatus); t.ok('El pago no agrega otro costo', '1000.00', (await D.get('/api/reports/costos')).totals.amount.value);
  t.ok('Fechas separadas: documento, autorización y pago', [true, true, true], [e.docDate === '2026-08-25', !!e.authorizedAt, e.payments?.[0]?.date === '2026-08-29']); t.ok('Una obligación y un desembolso para un comprobante', [1, 1, 1], [t.env.store.view().count('expenses'), t.env.store.view().count('obligations'), t.env.store.view().count('disbursements')]);
  const sn = await gasto(S, aux, { reference: 'N-42', subtotal: null, tax: null, total: '580', voucherTypeId: S.voucher.Nota || S.voucher.Factura }); const dn = await D.get(`/api/expenses/${sn.id}`); t.ok('Nota sin desglose: no se inventa el impuesto', [null, null, '580.00'], [dn.subtotal, dn.tax, dn.total]);
  const sinComp = await D.get('/api/expenses'); t.nota('Indicadores de pendientes en el listado', JSON.stringify(sinComp.items.map((x) => [x.folio, x.status, x.hasVoucher ?? x.attachment ?? null])));
});

caso('CAS-43', 'Caja chica', ['CAJ-02', 'CAJ-04'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const aux = await t.env.as('aux'); const f = await D.post('/api/petty-funds', { name: 'Fondo de obra A (auditoría)', responsibleId: S.s1Id, authorizedAmount: '2000', date: '2026-08-01' });
  await S.T.post(`/api/petty-funds/${f.id}/movements`, { kind: 'entrega', date: '2026-08-20', amount: '2000', accountId: S.caja }); t.ok('La entrega no es gasto', 0, t.env.store.view().count('expenses'));
  const g = await gasto(S, aux, { reference: 'C-43', subtotal: '1200', total: '1200', pettyFundId: f.id, allocations: [{ target: 'obra', workId: S.A, amount: '1200' }] }); await D.post(`/api/expenses/${g.id}/status`, { status: 'autorizado' });
  await aux.post(`/api/petty-funds/${f.id}/movements`, { kind: 'comprobacion', date: '2026-08-23', expenseId: g.id }); let fd = (await D.get('/api/petty-funds')).items[0]; t.nota('Fondo tras comprobar', JSON.stringify(fd).slice(0, 400)); t.ok('Efectivo restante $800 y por reponer $1,200', ['800.00', '1200.00'], [fd.balance, fd.toReplenish]);
  t.ok('El mismo recibo no se comprueba dos veces', 409, await st(aux, 'POST', `/api/petty-funds/${f.id}/movements`, { kind: 'comprobacion', date: '2026-08-24', expenseId: g.id }));
  const f2 = await D.post('/api/petty-funds', { name: 'Otro fondo (auditoría)', responsibleId: S.s2Id, authorizedAmount: '500', date: '2026-08-01' }); t.ok('Ni en otro fondo', true, [409, 422].includes(await st(aux, 'POST', `/api/petty-funds/${f2.id}/movements`, { kind: 'comprobacion', date: '2026-08-24', expenseId: g.id })));
  await S.T.post(`/api/petty-funds/${f.id}/movements`, { kind: 'reposicion', date: '2026-08-29', amount: '1200', accountId: S.caja }); fd = (await D.get('/api/petty-funds')).items.find((x) => x.id === f.id);
  t.ok('Fondo de vuelta en $2,000', ['2000.00', '0.00'], [fd.balance, fd.toReplenish]); t.ok('Gasto comprobado sigue en $1,200', ['1200.00', '1200.00'], [(await D.get('/api/expenses')).totals.total.value, (await D.get('/api/reports/costos')).totals.amount.value]);
  t.ok('Caja general: salieron $3,200 en total', '496800.00', await saldo(D, 'CAJA')); t.ok('Conciliación del fondo: entregas + reposiciones = disponible + comprobado', '3200.00', (Number(fd.balance) + Number(fd.verified)).toFixed(2));
  t.ok('Reponer más de lo comprobado', true, [409, 422].includes(await st(S.T, 'POST', `/api/petty-funds/${f.id}/movements`, { kind: 'reposicion', date: '2026-08-30', amount: '500', accountId: S.caja })));
});

caso('CAS-44', 'Prorrateo idempotente', ['GAS-11', 'GAS-12', 'GAS-13'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const aux = await t.env.as('aux'); await S.obligacion('30000'); await S.obligacion('70000', { workId: S.B }); const periodo = new Date().toISOString().slice(0, 7);
  const g = await gasto(S, aux, { reference: 'CS-44', description: 'Costo social de prueba', subtotal: '10000', total: '10000' }); const rule = await D.post('/api/allocation-rules', { name: 'Costo social por mano de obra (auditoría)', kind: 'costo_social', basis: 'mano_obra_autorizada' });
  t.ok('Regla sin aprobar no se aplica', 409, await st(D, 'POST', `/api/allocation-rules/${rule.id}/run`, { expenseId: g.id, period: periodo })); t.ok('Aprobar la regla sin motivo', 422, await st(D, 'POST', `/api/allocation-rules/${rule.id}/approve`, {}));
  await D.post(`/api/allocation-rules/${rule.id}/approve`, { reason: 'Criterio de prueba de la auditoría' }); const r1 = await D.post(`/api/allocation-rules/${rule.id}/run`, { expenseId: g.id, period: periodo }); t.nota('Resultado del prorrateo', JSON.stringify(r1).slice(0, 400));
  let e = await D.get(`/api/expenses/${g.id}`); t.ok('Asignaciones $3,000 / $7,000', ['3000.00', '7000.00'], e.allocations.map((a) => a.amount).sort()); t.ok('Asignado total', '10000.00', e.allocated);
  t.ok('Reejecutar sin motivo', 422, await st(D, 'POST', `/api/allocation-rules/${rule.id}/run`, { expenseId: g.id, period: periodo })); await D.post(`/api/allocation-rules/${rule.id}/run`, { expenseId: g.id, period: periodo, reason: 'Repetición controlada (auditoría)' });
  e = await D.get(`/api/expenses/${g.id}`); t.ok('Reejecutar no duplica: sigue en $10,000', ['10000.00', 2], [e.allocated, e.allocations.length]); const runs = t.env.store.view().by('allocationRuns', 'expenseId', g.id); t.ok('Cada ejecución conserva periodo, base, resultado y redondeo', [2, true], [runs.length, runs.every((r) => r.period && r.basis && r.result && r.roundingDiff !== undefined)]);
  await D.post(`/api/expenses/${g.id}/status`, { status: 'autorizado' }); t.ok('Costo total $10,000 más mano de obra $100,000', '110000.00', (await D.get('/api/reports/costos')).totals.amount.value);
  t.ok('Un gasto ya autorizado no se vuelve a prorratear', 409, await st(D, 'POST', `/api/allocation-rules/${rule.id}/run`, { expenseId: g.id, period: periodo, reason: 'intento posterior (auditoría)' }));
  const sinBase = await gasto(S, aux, { reference: 'CS-44b', total: '500', subtotal: '500' }); t.ok('Sin base en el periodo no se reparte por partes iguales', 409, await st(D, 'POST', `/api/allocation-rules/${rule.id}/run`, { expenseId: sinBase.id, period: '2020-01' }));
  t.ok('Auxiliar no crea ni aplica reglas', true, [403, 404].includes(await st(aux, 'POST', `/api/allocation-rules/${rule.id}/run`, { expenseId: sinBase.id, period: periodo })));
});

caso('CAS-45', 'Insumos', ['INS-01', 'INS-02', 'INS-03', 'INS-04', 'INS-05', 'INS-06'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const aux = await t.env.as('aux'); const g = await gasto(S, aux, { reference: 'I-45', subtotal: '5000', total: '5000', description: '50 sacos de adhesivo' });
  const sup = (await D.post('/api/catalog/supplies', { name: 'Adhesivo en saco (auditoría)', unitId: S.unit.saco || S.unit.bulto })).id; const mv = (o) => aux.try('POST', '/api/supplies/movements', { supplyId: sup, ...o });
  t.ok('Recepción de 50', 200, (await mv({ kind: 'recepcion', date: '2026-08-25', qty: '50', expenseId: g.id, unitCost: '100' })).status); let s0 = (await aux.get('/api/supplies/stock')).items[0]; t.ok('La compra no es consumo', ['50.0000', '0.0000', '0.0000'], [s0.inStore, s0.atWorks, s0.consumed]);
  t.ok('Entregar 30 a A', 200, (await mv({ kind: 'entrega_obra', date: '2026-08-26', qty: '30', workId: S.A })).status); t.ok('Consumir 25 en A', 200, (await mv({ kind: 'consumo', date: '2026-08-27', qty: '25', workId: S.A })).status);
  t.ok('Devolver 5 al almacén', 200, (await mv({ kind: 'devolucion', date: '2026-08-28', qty: '5', workId: S.A })).status); s0 = (await aux.get('/api/supplies/stock')).items[0];
  t.ok('Almacén 25, en obra 0, consumido 25', ['25.0000', '0.0000', '25.0000'], [s0.inStore, s0.atWorks, s0.consumed]); t.nota('Existencia por obra', JSON.stringify(s0.byWork)); t.ok('Sin existencias negativas en la secuencia correcta', false, s0.negative);
  // Sondas negativas con otro insumo, para no contaminar la conciliación anterior.
  const sup2 = (await D.post('/api/catalog/supplies', { name: 'Boquilla (auditoría)', unitId: S.unit.saco || S.unit.bulto })).id; const mv2 = (o) => aux.try('POST', '/api/supplies/movements', { supplyId: sup2, ...o }); await mv2({ kind: 'recepcion', date: '2026-08-25', qty: '10' });
  const e1 = await mv2({ kind: 'entrega_obra', date: '2026-08-26', qty: '25', workId: S.B }); const e2 = await mv2({ kind: 'consumo', date: '2026-08-27', qty: '40', workId: S.B }); const s2 = (await aux.get('/api/supplies/stock')).items.find((x) => x.id === sup2);
  t.nota('Entregar 25 con 10 en almacén y consumir 40 con 25 en obra', JSON.stringify({ entrega: e1.status, consumo: e2.status, inStore: s2.inStore, atWorks: s2.atWorks, negative: s2.negative, mensaje: e1.data.message || e1.data.warnings || null }));
  t.cierto('Entregar más de la existencia se bloquea o exige una política/justificación', [409, 422].includes(e1.status) || /negativ|existencia/i.test(JSON.stringify(e1.data)), `${e1.status} → almacén ${s2.inStore}`); t.cierto('Consumir más de lo entregado a la obra se bloquea o exige justificación', [409, 422].includes(e2.status) || /negativ|existencia/i.test(JSON.stringify(e2.data)), `${e2.status} → en obra ${s2.atWorks}`);
  t.ok('La existencia negativa queda marcada (no se oculta)', true, s2.negative);
  const rep = await D.get('/api/reports/insumos'); t.nota('Reporte de consumos (¿valora el costo?)', JSON.stringify(rep.items).slice(0, 400)); t.cierto('El consumo de A se valora en $2,500', /2500\.00/.test(JSON.stringify(rep.items)) || /2500\.00/.test(JSON.stringify(s0)), 'no aparece un costo de consumo de $2,500 en existencias ni en el reporte');
  await aux.put(`/api/expenses/${g.id}/allocations`, { allocations: [{ target: 'stock', amount: '5000' }] }).catch(async (e) => t.nota('Asignar la compra a stock', `${e.status} ${e.data?.message}`)); await D.post(`/api/expenses/${g.id}/status`, { status: 'autorizado' }).catch(async (e) => t.nota('Autorizar la compra para stock', `${e.status} ${e.data?.message} ${JSON.stringify(e.data?.reasons || '')}`));
  const costos = await D.get('/api/reports/costos'); t.nota('Costos tras la compra para stock', JSON.stringify(costos.items.map((x) => [x.work, x.category, x.amount]))); t.cierto('La compra de $5,000 no se imputa íntegra como costo de A', !costos.items.some((x) => /Obra A/.test(x.work) && x.amount === '5000.00'), costos.items.map((x) => [x.work, x.amount]));
  const pieza = await mv({ kind: 'entrega_obra', date: '2026-08-29', qty: '1', workId: S.A, unitId: S.unit.pza || S.unit.pieza }); t.nota('Movimiento en otra unidad sin conversión registrada', `${pieza.status} ${pieza.data.message || ''}`);
  const ratio = await aux.get(`/api/supplies/ratio?supplyId=${sup}&workId=${S.A}&conceptIds=${S.piso}&from=2026-08-01&to=2026-08-31`); t.ok('Sin superficie ejecutada el consumo por m² no es calculable (ni cero)', [null, false], [ratio.ratio, ratio.reliable]);
});

caso('CAS-46', 'Traspaso interno', ['TES-02', 'SEM-01'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const c = (await D.post('/api/catalog/accounts', { code: 'CJ46', name: 'Caja 46 (auditoría)', kind: 'efectivo', currency: 'MXN', openingBalance: '5000', openingDate: '2026-01-01' })).id; const b = (await D.post('/api/catalog/accounts', { code: 'BN46', name: 'Banco 46 (auditoría)', kind: 'banco', currency: 'MXN', openingBalance: '10000', openingDate: '2026-01-01' })).id;
  const r0 = await D.get('/api/results?from=2026-01-01&to=2026-12-31'); const tr = await S.T.post('/api/cash/transfers', { fromAccountId: b, toAccountId: c, date: '2026-08-28', amount: '2000' }); t.nota('Transferencia', JSON.stringify(tr).slice(0, 200));
  t.ok('Saldos', ['7000.00', '8000.00'], [await saldo(D, 'CJ46'), await saldo(D, 'BN46')]); const r1 = await D.get('/api/results?from=2026-01-01&to=2026-12-31');
  t.ok('Resultado sin cambio', r0.result.lines.map((l) => l.value), r1.result.lines.map((l) => l.value)); t.ok('Flujo de operación sin cambio y transferencia neta cero', [r0.cashFlow.classes.operacion.net, '0.00'], [r1.cashFlow.classes.operacion.net, r1.cashFlow.classes.transferencia.net]);
  const mv = (await D.get('/api/cash/movements')).items.filter((m) => /transferencia/.test(m.type)); t.ok('Salida y entrada vinculadas', [2, true], [mv.length, mv.every((m) => m.transferId || m.linkedId || m.pairId || m.sourceId)]);
  t.ok('Transferir más del saldo', true, [409, 422].includes(await st(S.T, 'POST', '/api/cash/transfers', { fromAccountId: c, toAccountId: b, date: '2026-08-29', amount: '999999' }))); t.ok('Transferir a la misma cuenta', 422, await st(S.T, 'POST', '/api/cash/transfers', { fromAccountId: c, toAccountId: c, date: '2026-08-29', amount: '1' }));
});

caso('CAS-47', 'Margen consolidado', ['REP-03', 'RES-01'], async (t) => {
  const S = await escenario(t.env); const D = S.D; const mk = async (workId, loc, price, cost) => { const b = await S.presupuesto([{ chapter: 'PISOS', locationId: loc, conceptId: S.kPiso, description: 'Piso', unitId: S.unit.m2, qty: '10', price }], workId); await D.post(`/api/works/${workId}/contracts`, { termsValidated: true, taxRate: '0', taxLabel: 'Sin impuesto (solo prueba)' });
    const who = workId === S.A ? S.s1 : S.s2; await S.validado({ workId, locationId: loc, conceptId: S.piso, executionDate: '2026-08-24', qty: '1', budgetItemId: b.items[0] }, who); const k = await D.post('/api/k-estimates', { workId, periodFrom: '2026-08-01', periodTo: '2026-08-31' }); await D.post(`/api/k-estimates/${k.id}/generate`, {}); await D.post(`/api/k-estimates/${k.id}/transition`, { to: 'revision_interna' }); await D.post(`/api/k-estimates/${k.id}/transition`, { to: 'enviada' });
    await D.post(`/api/k-estimates/${k.id}/register-approval`, { approvedByName: 'Representante (auditoría)', reason: 'Aprobación por correo (auditoría)' }); await S.obligacion(cost, { workId }); };
  await mk(S.A, S.pb, '100', '90'); await mk(S.B, S.locB, '900', '450'); const r0 = await D.get('/api/results?from=2026-01-01&to=2026-12-31'); t.nota('Resultado con obras sin clasificar', JSON.stringify({ lines: r0.result.lines.map((l) => [l.key, l.value]), pendientes: r0.result.pendings || r0.pendings || null }).slice(0, 500));
  for (const w of [S.A, S.B]) { const pt = await D.try('PATCH', `/api/works/${w}`, { consolidation: 'incluida' }); if (pt.status !== 200) t.nota('Clasificar obra para consolidación', `${pt.status} ${pt.data.message}`); } const mA = (await D.get(`/api/works/${S.A}/summary`)).margin, mB = (await D.get(`/api/works/${S.B}/summary`)).margin;
  t.ok('Obra A: ingreso 100, costo 90', ['100.00', '90.00', '10.00'], [mA.revenue, mA.costs, mA.amount]); t.ok('Obra B: ingreso 900, costo 450', ['900.00', '450.00', '450.00'], [mB.revenue, mB.costs, mB.amount]); t.nota('Porcentajes por obra', JSON.stringify([mA.pct, mB.pct]));
  const res = await D.get('/api/results?from=2026-01-01&to=2026-12-31'); t.nota('Resultado de empresa (obras incluidas)', JSON.stringify({ lines: res.result.lines.map((l) => [l.key, l.value, l.pct ?? null]), partial: res.result.partial, pendientes: res.result.pendings || null }).slice(0, 600)); const L = Object.fromEntries(res.result.lines.map((l) => [l.key, l.value])); t.ok('Consolidado: ingreso 1,000, costo 540, margen 460', ['1000.00', '540.00', '460.00'], [L.ingresos, L.costo, L.bruta]);
  const q = await D.post('/api/analytics/query', { dataset: 'resultado_obra', groupBy: 'work', measures: ['revenue', 'costs', 'margin', 'marginPct'] }).catch((e) => ({ err: `${e.status} ${e.data?.message}` })); t.nota('Explorador: resultado por obra', JSON.stringify(q.err || { rows: q.rows, totals: q.totals }).slice(0, 500));
  const ds = (await D.get('/api/analytics/datasets')).items.map((x) => [x.code, x.measures.map((m) => m.key + ':' + m.type)]); t.nota('Conjuntos y medidas del explorador', JSON.stringify(ds).slice(0, 900));
  const txt = JSON.stringify([res, q]); t.ok('No aparece un margen promedio de 30 %', false, /"(pct|marginPct)":"30\.0+"/.test(txt)); t.cierto('El margen consolidado disponible es 46 % (460 / 1,000)', /46\.0+/.test(txt), 'no se encontró un porcentaje consolidado de 46 % en resultados ni en el explorador');
  const zero = (await D.get(`/api/works/${S.A}/summary`)); void zero; const sinIngreso = await escenarioSinIngreso(); t.ok('Sin ingreso el porcentaje es "no calculable", no 0 % ni infinito', null, sinIngreso);
});
