// Libro mínimo con la forma del control de obra (perfil "estimaciones").
async function libro({ nombre = 'Balcones', year2 = 2026, q35 = 72.08, error = false, marca = '' } = {}) {
  const wb = new ExcelJS.Workbook(); const w0 = wb.addWorksheet(`${nombre} anexo`); w0.getCell('B2').value = `CONTROL DE OBRA  - ${nombre} anexo`; ['CLAVE', 'CONCEPTO', 'CANTIDAD', 'UNIDAD', 'PU', 'IMPORTE'].forEach((v, i) => { w0.getCell(6, 2 + i).value = v; });
  const ws = wb.addWorksheet(nombre); ws.getCell('B2').value = `CONTROL DE OBRA  - ${nombre}`; if (marca) ws.getCell('A1').value = marca;
  ['CLAVE', 'CONCEPTO', 'CANTIDAD', 'UNIDAD', 'PU', 'IMPORTE'].forEach((v, i) => { ws.getCell(6, 2 + i).value = v; });
  [[8, 2026, 'Semana 34', '17 - 22 Agosto'], [10, year2, 'Semana 35', '24 - 29 Agosto']].forEach(([c, y, w, r]) => { ws.getCell(5, c).value = y; ws.getCell(6, c).value = w; ws.getCell(7, c).value = r; ws.getCell(8, c).value = 'CANT.'; ws.getCell(8, c + 1).value = 'IMPORTE'; });
  ws.getCell(6, 12).value = 'EJECUTADO'; ws.getCell('B9').value = 'PISOS INTERIORES';
  const row = (r, c, q, u, pu, q34, q35v) => { ws.getCell(r, 3).value = c; ws.getCell(r, 4).value = q; ws.getCell(r, 5).value = u; ws.getCell(r, 6).value = pu; if (q34) { ws.getCell(r, 8).value = q34; ws.getCell(r, 9).value = q34 * pu; } if (q35v) { ws.getCell(r, 10).value = q35v; ws.getCell(r, 11).value = q35v * pu; } };
  row(10, 'Partida uno', 10, 'm2', 100, 1, 0); row(11, 'Partida dos', 10, 'm2', 100, 2, q35);
  if (error) ws.getCell(11, 12).value = { formula: 'NOEXISTE(K11)', result: { error: '#NAME?' } };
  ws.getCell(16, 3).value = 'TOTAL DE PTTO.'; ws.getCell(16, 9).value = { formula: 'SUM(I9:I15)', result: 300 }; ws.getCell(16, 11).value = { formula: 'SUM(K9:K15)', result: q35 * 100 };
  return Buffer.from(await wb.xlsx.writeBuffer());
}
const subir = (adm, name, buf) => adm.call('POST', `/api/imports?name=${encodeURIComponent(name)}`, buf).then((r) => { if (r.status >= 400) throw Object.assign(new Error(`Carga rechazada: ${r.data.message}`), { data: r.data }); return r.data; });

