  const S = await escenario(t.env); const adm = await t.env.as('adm'); const b1 = await subir(adm, 'AUD_Estimaciones_a.xlsx', await libro({ q35: 72.08 })); const s1 = await adm.post(`/api/imports/${b1.id}/simulate`);
  await adm.post(`/api/imports/${b1.id}/confirm`, { strategy: 'solo_evidencia' }); const b2 = await subir(adm, 'AUD_Estimaciones_b.xlsx', await libro({ q35: 72.78, marca: 'otra versión' })); const s2 = await adm.post(`/api/imports/${b2.id}/simulate`);
