  const recs = await adm.get(`/api/imports/${b2.id}/records`); const conf = recs.items.filter((r) => /72\.78/.test(JSON.stringify(r))); t.nota('Registro en conflicto', JSON.stringify(conf[0] || null).slice(0, 500)); t.cierto('El registro en conflicto muestra el valor anterior (72.08) junto al nuevo', conf.some((r) => /72\.08/.test(JSON.stringify(r))), 'el registro nuevo no referencia el valor anterior');
  const b3 = await subir(adm, 'AUD_Estimaciones_c.xlsx', await libro({ nombre: 'Balcones dos', year2: 2025 })); const s3 = await adm.post(`/api/imports/${b3.id}/simulate`); t.ok('Año incongruente entre semanas contiguas: conflicto de fecha explícito', true, (s3.issues.fecha_conflicto || 0) >= 1); t.nota('Incidencias del libro con año 2025 en la semana 35', JSON.stringify(s3.issues));
  const c2 = await adm.try('POST', `/api/imports/${b2.id}/confirm`, { strategy: 'solo_evidencia' }); t.nota('Confirmar el libro con la cantidad distinta sin resolver el conflicto', `${c2.status} ${JSON.stringify(c2.data).slice(0, 300)}`);
