  // Dos acumulados simultáneos contra la misma base.
  const base = await S.capturar(S.s1, { locationId: S.sot, conceptId: S.piso, executionDate: '2026-08-24', mode: 'acumulado', qty: '40' }); await D.post(`/api/progress/${base.id}/review`, { decision: 'validar' });
