  const ar = await D.get('/api/receivables'); t.ok('Cliente: saldo de la estimación', '17000.00', ar.items[0].balance); const cli = await S.c1.get(`/api/k-estimates/${k.id}`); const ctxt = JSON.stringify(cli); t.ok('El cliente no ve tarifas del contratista, márgenes ni al supervisor', [false, false, false, false], [/350\.0000/.test(ctxt), /K1 Contratista/.test(ctxt), /S1 Supervisor/.test(ctxt), /margin|internalNotes/.test(ctxt)]);
  t.ok('El contratista no ve el precio al cliente ni el presupuesto', [false, 404], [/1000\.0000|30000\.00/.test(JSON.stringify(await S.k1.get(`/api/c-estimates/${est.id}`))), await st(S.k1, 'GET', `/api/works/${S.A}/budget-tracking`)]);
  // 7 · Trazabilidad del origen al saldo.
  const pe = await D.get(`/api/progress/${e1.id}`); t.nota('Avance e1: vínculos', JSON.stringify({ paidQty: pe.paidQty, billedQty: pe.billedQty ?? pe.clientQty, circuits: pe.circuits || pe.allocations || null }).slice(0, 400)); t.cierto('El avance muestra en qué documento de pago y de cobro quedó', /EC-|EK-/.test(JSON.stringify(pe)), 'el detalle del avance no referencia sus documentos');
  const tasks = await D.get('/api/home/tasks'); t.nota('Pendientes con responsable (bandeja de dirección)', JSON.stringify(tasks.items.map((x) => [x.group, x.title])).slice(0, 500)); t.cierto('Lo pendiente (observación abierta, saldo por pagar, estimación en borrador) aparece en la bandeja', tasks.items.length >= 2, tasks.items.length);
  t.ok('Auditoría íntegra al final del recorrido', true, (await (await t.env.as('aud')).get('/api/audit/verify')).ok); t.ok('Estructura válida', [], validateAll(t.env.store.view()));
  t.ok('Caja y banco reconstruibles', ['495000.00', '1015000.00'], [await saldo(D, 'CAJA'), await saldo(D, 'BANCO')]);
